    return None


def count_solutions(board, limit, shuffled):
    """Count solutions up to `limit`; leaves the board filled when a solution is found."""
    if limit <= 0:
        return 0
    pos = find_empty(board)
    if pos is None:
        return 1
    r, c = pos
    nums = list(range(1, N + 1))
