        random.shuffle(nums)
    total = 0
    for v in nums:
        if is_valid(board, r, c, v):
            board[r][c] = v
            total += count_solutions(board, limit - total, shuffled)
            if total >= limit:
                return total
            board[r][c] = 0
    return total


def generate(clues):
