    target = 81 - clues
    for r, c in cells:
        if removed >= target:
            break
        backup = puzzle[r][c]
        puzzle[r][c] = 0
        if _count_solutions([row[:] for row in puzzle]) != 1:
            puzzle[r][c] = backup
        else:
            removed += 1
    return puzzle, solution


def find_conflicts(board):
    """Return a set of (row, col) cells violating row/column/3x3-box rules."""
    conflicts = set()
    units = []
    for i in range(9):
        units.append([(i, c) for c in range(9)])
        units.append([(r, i) for r in range(9)])
    for br in range(0, 9, 3):
        for bc in range(0, 9, 3):
            units.append([(br + r, bc + c) for r in range(3) for c in range(3)])
    for unit in units:
        seen = {}
        for r, c in unit:
            v = board[r][c]
            if v != 0:
                if v in seen:
                    conflicts.add((r, c))
                    conflicts.add(seen[v])
                else:
                    seen[v] = (r, c)
    return conflicts


def is_complete(board):
    """True when every cell is filled 1-9 with no rule conflicts."""
    return (all(board[r][c] != 0 for r in range(9) for c in range(9))
            and not find_conflicts(board))
